-- 세트 114: Kafka 문제 해결 상황집: lag, 리밸런싱, 접속 오류, 복제, 디스크
-- 기본기 사다리(docs/specs/spec_foundations_ladder.md). 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (114, 1, '장애 때 먼저 치는 점검 명령', '컨슈머가 밀린다는 신고가 들어왔습니다. ① 컨슈머 그룹 **목록**을 보고, ② 복제가 따라가지 못하는(**under-replicated**) 파티션만 골라 봅니다. 빈칸을 채우세요.', '목록은 list, 파티션 상태는 describe 예요.', NULL, NULL, '[]', 'fill', '["list", "describe", "create", "delete"]', NULL, '`--list` 는 어떤 그룹이 있는지, `--describe --under-replicated-partitions` 는 팔로워가 리더를 따라잡지 못한 파티션만 보여 줍니다. 결과가 비어 있으면 복제는 정상이라는 뜻이니, 장애 때 가장 먼저 치는 두 줄이에요.', '[0, 1]', 'kafka-consumer-groups.sh --bootstrap-server broker:9092 --{0}
kafka-topics.sh --bootstrap-server broker:9092 --{1} --under-replicated-partitions', NULL, NULL),
  (114, 2, 'lag 출력 읽기', '그룹 `orders` 를 `--describe` 했더니 아래와 같았습니다. 가장 알맞은 해석은 무엇일까요?

```
TOPIC   PARTITION  CURRENT-OFFSET  LOG-END-OFFSET  LAG
orders  0          90210           90210           0
orders  1          41002           89212           48210
orders  2          88740           88740           0
```', '파티션 1 한 곳만 LAG 가 큽니다. 전체가 아니라 한 곳이 문제예요.', NULL, NULL, '[]', 'choice', '["브로커 전체가 느려졌다", "파티션 1 을 맡은 컨슈머만 멈췄거나 느리다. 해당 컨슈머의 로그와 처리 중인 메시지를 먼저 본다", "토픽을 삭제하고 다시 만들어야 한다", "컨슈머 그룹 ID 를 바꾸면 해결된다"]', 1, '모든 파티션이 밀리면 소비 전체가 느린 것이고, **한 파티션만** 밀리면 그 파티션을 맡은 컨슈머(또는 그 파티션에 몰린 키·무거운 메시지)가 원인일 가능성이 큽니다. 그룹 ID 를 바꾸면 lag 이 사라진 듯 보여도 읽기 위치가 달라져 유실이나 중복이 생겨요.', NULL, NULL, NULL, NULL),
  (114, 3, 'Broker may not be available', '프로듀서 로그에 `Connection to node -1 (broker:9092) could not be established. Broker may not be available.` 가 반복됩니다. 가장 먼저 확인할 것은 무엇일까요?', '`node -1` 은 아직 브로커 목록을 받기 전, 처음 접속하려는 부트스트랩 주소를 뜻해요.', NULL, NULL, '[]', 'choice', '["토픽의 파티션 수", "컨슈머 그룹의 오프셋", "메시지 압축 방식", "`bootstrap.servers` 의 주소·포트가 맞는지, 그 주소로 네트워크(방화벽, DNS)가 닿는지"]', 3, '부트스트랩 단계에서 막힌 것이라 설정한 주소로 연결 자체가 안 되는 상황입니다. 오타, 포트, 방화벽, 이름 해석(DNS)을 순서대로 확인하세요. 접속은 되는데 그다음에 실패한다면 advertised 주소 문제를 의심합니다.', NULL, NULL, NULL, NULL),
  (114, 4, '접속은 되는데 그다음에 실패해요', '컨테이너 밖 클라이언트가 부트스트랩 접속은 성공하지만, 이어서 `Connection to localhost:9092 failed` 가 납니다. 브로커가 **자기 주소를 localhost 로 알려 주고 있기 때문**입니다. 클라이언트가 실제로 닿을 수 있는 이름으로 알리도록 빈칸을 채우세요.', '클라이언트 입장에서 "닿는 주소"는 브로커의 바깥 이름이에요.', NULL, NULL, '[]', 'fill', '["broker1.example.com", "localhost", "0.0.0.0", "127.0.0.1"]', NULL, '`listeners` 는 브로커가 **듣는** 곳이고, `advertised.listeners` 는 클라이언트에게 **알려 주는** 주소입니다. 클라이언트는 부트스트랩 뒤 이 알려 준 주소로 다시 접속하므로 localhost, 0.0.0.0 은 클라이언트에게 닿지 않아요.', '[0]', 'listeners=PLAINTEXT://0.0.0.0:9092
advertised.listeners=PLAINTEXT://{0}:9092', NULL, NULL),
  (114, 5, 'lag 이 계속 늘 때 점검 순서', 'lag 이 계속 늘고 있습니다. 보통 이 순서로 원인을 좁힙니다. 순서에 맞게 놓아 보세요.', '큰 그림(어느 파티션?)에서 작은 원인으로 내려가요.', NULL, NULL, '[]', 'order', '["파티션별 lag 으로 전체인지 일부인지 본다", "컨슈머 로그에서 예외·재시작을 찾는다", "메시지 처리 시간과 외부 호출 지연을 본다", "리밸런싱이 잦은지 확인한다", "그래도 부족하면 파티션 수 이하로 컨슈머를 늘린다"]', NULL, '증상의 범위를 먼저 보고(전체/일부), 에러와 재시작, 처리 시간, 리밸런싱을 차례로 확인합니다. 컨슈머를 늘리는 것은 **마지막** 수단입니다. 원인이 처리 지연이나 에러라면 늘려도 해결되지 않아요.', '[0, 1, 2, 3, 4]', NULL, NULL, NULL),
  (114, 6, 'poll 간격을 넘겼어요', '컨슈머 로그에 `CommitFailedException: ... the time between subsequent calls to poll() was longer than max.poll.interval.ms` 가 납니다. 처리가 오래 걸려 그룹에서 쫓겨난 것입니다. 해결 방향의 빈칸을 채우세요.', '허용 시간은 늘리고, 한 번에 가져오는 양은 줄여요.', NULL, NULL, '[]', 'fill', '["max.poll.interval.ms", "max.poll.records", "session.timeout.ms", "acks"]', NULL, '`max.poll.interval.ms` 는 poll 사이에 허용하는 최대 시간, `max.poll.records` 는 한 번에 가져오는 메시지 수입니다. 한 번에 적게 가져와 빨리 끝내거나 허용 시간을 늘리면 쫓겨나지 않아요. 근본적으로는 처리가 느린 이유(외부 호출 등)도 함께 봐야 합니다.', '[0, 1]', '{0} 를 늘리거나
{1} 를 줄인다', NULL, NULL),
  (114, 7, '리밸런싱이 끝없이 반복돼요', '컨슈머 로그에 `Revoking previously assigned partitions`, `Successfully joined group` 이 몇 분 간격으로 계속 반복되고 그동안 lag 이 늘어납니다. 가장 먼저 의심할 것은 무엇일까요?', '리밸런싱은 컨슈머가 그룹에 들어오거나 나갈 때 일어납니다.', NULL, NULL, '[]', 'choice', '["컨슈머가 반복해서 재시작되거나, 처리가 느려 poll 간격·세션 시간을 넘겨 그룹에서 계속 쫓겨난다", "브로커의 디스크 용량이 많이 남아 있다", "토픽 이름이 너무 길다", "메시지 키가 문자열이다"]', 0, '리밸런싱 중에는 소비가 멈추므로 잦으면 lag 이 쌓입니다. 컨슈머 재시작 횟수(크래시, OOM, 배포)와 `max.poll.interval.ms` 초과 로그를 먼저 확인하세요.', NULL, NULL, NULL, NULL),
  (114, 8, '컨슈머를 늘렸는데 그대로예요', '파티션이 3개인 토픽을 컨슈머 6개로 읽도록 늘렸지만 lag 이 줄지 않습니다. 이유로 알맞은 것은 무엇일까요?', '파티션 하나는 같은 그룹 안에서 한 컨슈머만 읽을 수 있어요.', NULL, NULL, '[]', 'choice', '["컨슈머가 많을수록 항상 느려진다", "lag 은 컨슈머 수와 상관없이 자동으로 줄어든다", "같은 그룹에서는 파티션 하나를 한 컨슈머만 읽으므로, 3개를 초과한 컨슈머는 할 일이 없다. 파티션을 늘리거나 처리 속도를 개선해야 한다", "컨슈머를 홀수로 맞춰야 한다"]', 2, '병렬도의 상한은 파티션 수입니다. 파티션을 늘리면 처리량은 늘 수 있지만 키별 배치가 바뀌어 순서 보장에 영향이 있으니 신중히 정해야 해요.', NULL, NULL, NULL, NULL),
  (114, 9, '같은 메시지에서 계속 실패해요', '컨슈머가 특정 오프셋의 메시지에서 역직렬화 예외를 내고 재시작하며 같은 메시지를 계속 다시 읽습니다. lag 은 그 지점에서 멈춘 채입니다. 올바른 대응은 무엇일까요?', '이런 메시지를 흔히 poison pill(독이 든 알약)이라고 불러요.', NULL, NULL, '[]', 'choice', '["컨슈머를 계속 재시작한다", "예외를 잡아 문제 메시지를 DLQ(별도 토픽)로 보내고 다음 메시지로 넘어가게 한 뒤, 보관한 메시지로 원인을 분석한다", "토픽 전체를 삭제한다", "로그 레벨을 낮춰 에러를 보이지 않게 한다"]', 1, '한 메시지가 전체 소비를 막는 것을 막으려면 실패한 메시지를 따로 빼 두는 **DLQ** 가 필요합니다. 오프셋을 건너뛰기만 하면 그 메시지는 영영 사라지니, 건너뛰기 전에 내용을 보관하세요.', NULL, NULL, NULL, NULL),
  (114, 10, 'under-replicated 대응 순서', '`--under-replicated-partitions` 에 파티션이 계속 나옵니다. 순서에 맞게 놓아 보세요.', '어느 브로커가 문제인지부터 찾아요.', NULL, NULL, '[]', 'order', '["under-replicated 파티션이 어느 브로커에 몰려 있는지 확인한다", "해당 브로커의 프로세스·로그·디스크를 확인한다", "원인(디스크, 메모리, 네트워크)을 해결하고 브로커를 정상화한다", "ISR 이 복구되어 under-replicated 가 사라졌는지 다시 확인한다"]', NULL, '대상 브로커 → 그 브로커의 상태 → 원인 해결 → 결과 재확인 순입니다. 마지막에 같은 명령을 다시 쳐서 비었는지 확인해야 복구가 끝난 거예요.', '[0, 1, 2, 3]', NULL, NULL, NULL),
  (114, 11, '브로커 디스크가 가득 찼어요', '브로커 로그에 `No space left on device` 가 나고 브로커가 내려갔습니다. 올바른 조치는 무엇일까요?', '데이터 파일은 브로커가 관리해요. 직접 지우지 마세요.', NULL, NULL, '[]', 'choice', '["로그 디렉터리의 세그먼트 파일을 rm 으로 직접 지운다", "컨슈머를 모두 삭제한다", "메시지 키를 바꾼다", "토픽별 보관 설정(`retention.ms`, `retention.bytes`)과 사용량을 확인하고, 설정을 조정하거나 디스크를 늘린 뒤 브로커를 올린다"]', 3, '세그먼트 파일을 직접 지우면 인덱스와 어긋나 브로커가 더 크게 망가질 수 있습니다. 보관 정책으로 정리되도록 하거나 용량을 확보하세요. 어느 토픽이 많이 차지하는지 먼저 봐야 합니다.', NULL, NULL, NULL, NULL),
  (114, 12, 'min.insync.replicas 와 장애', '복제 계수 3, 프로듀서 `acks=all`, 토픽 `min.insync.replicas=2` 입니다. 브로커 2대가 내려가 ISR 이 1개만 남았을 때 어떻게 될까요? 빈칸을 채우세요.', 'acks=all 은 ISR 중 최소 개수만큼 복제돼야 성공이에요.', NULL, NULL, '[]', 'fill', '["실패", "성공", "가능", "불가"]', NULL, '남은 ISR 이 `min.insync.replicas` 보다 적으면 `acks=all` 쓰기는 거부되어 데이터 안전을 지킵니다. 리더가 살아 있으면 이미 커밋된 데이터는 읽을 수 있어요. 가용성보다 안전을 택한 설정의 결과입니다.', '[0, 2]', '쓰기는 {0} (NotEnoughReplicas), 이미 저장된 데이터 읽기는 {1}', NULL, NULL),
  (114, 13, '오프셋 리셋 전에 확인하기', 'lag 을 없애려고 오프셋을 최신으로 옮기려 합니다. 이 명령은 쌓인 메시지를 **처리하지 않고 건너뛰는** 위험한 작업이라, 먼저 실제로 적용하지 않고 결과만 보는 옵션으로 실행해야 합니다. 빈칸을 채우세요.', '"예행연습"을 뜻하는 옵션이에요.', NULL, NULL, '[]', 'fill', '["dry-run", "execute", "describe", "force"]', NULL, '`--dry-run` 은 바뀔 오프셋만 보여 주고 적용하지 않습니다. 실제 적용은 `--execute` 이고, 그룹이 비활성(컨슈머 중지) 상태여야 하며, 건너뛰는 메시지가 처리하지 않아도 되는지 먼저 확인해야 합니다.', '[0]', 'kafka-consumer-groups.sh --bootstrap-server broker:9092 --group orders --topic orders --reset-offsets --to-latest --{0}', NULL, NULL);
